<?php
require_once __DIR__.'/includes/auth.php';require_login();require_once __DIR__.'/includes/olympia_store.php';olympia_ensure_schema();if(!olympia_admin()){http_response_code(403);exit('Chỉ quản trị được xem bảng xếp hạng toàn trường.');}
$period=in_array($_GET['period']??'',['week','month'],true)?$_GET['period']:'week';$weekId=trim((string)($_GET['week']??''));$month=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['month']??''))?(string)$_GET['month']:date('Y-m');$weeks=olympia_weeks();if($weekId===''&&$weeks)$weekId=(string)$weeks[0]['id'];
$db=olympia_db();if($period==='month'){$where="WHERE DATE_FORMAT(COALESCE(w.open_at,w.created_at),'%Y-%m')=?";$args=[$month];}else{$where='WHERE s.week_id=?';$args=[$weekId];}
$sql="SELECT s.class_id,s.class_name,SUM(s.points) points,COUNT(*) correct,COUNT(DISTINCT s.student_id) students FROM cds_olympia_scores s JOIN cds_olympia_weeks w ON w.id=s.week_id $where GROUP BY s.class_id,s.class_name ORDER BY points DESC,s.class_name";$st=$db->prepare($sql);$st->execute($args);$classes=$st->fetchAll();
$sql2="SELECT s.student_name,s.class_name,SUM(s.points) points,COUNT(*) correct FROM cds_olympia_scores s JOIN cds_olympia_weeks w ON w.id=s.week_id $where GROUP BY s.student_id,s.student_name,s.class_name ORDER BY points DESC,s.student_name LIMIT 100";$st=$db->prepare($sql2);$st->execute($args);$students=$st->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Xếp hạng Olympia</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#061941;font-family:Segoe UI,system-ui}.hero{background:linear-gradient(120deg,#09265d,#0873b9);color:#fff;border-bottom:3px solid #ffd32a}.wrap{max-width:1250px}.card{border:0;border-radius:18px}.rank{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#e8f2fb;font-weight:900}.rank.top{background:#ffd32a}.table thead th{background:#e6f1fb;color:#174b76}.points{font-size:1.25rem;font-weight:900;color:#075ea8}</style></head><body><header class="hero"><div class="container wrap py-4 d-flex align-items-center"><div><div class="text-warning fw-bold">ĐƯỜNG LÊN ĐỈNH OLYMPIA</div><h1 class="fw-bold mb-0">Bảng xếp hạng các lớp</h1></div><a class="btn btn-outline-light ms-auto" href="<?=BASE_URL?>hoclieu_game_olympia.php">Quản lý Olympia</a></div></header><main class="container wrap py-4"><div class="card p-3 mb-3"><form class="row g-2"><div class="col-md-3"><select class="form-select" name="period" onchange="this.form.submit()"><option value="week" <?=$period==='week'?'selected':''?>>Theo tuần</option><option value="month" <?=$period==='month'?'selected':''?>>Theo tháng</option></select></div><?php if($period==='week'):?><div class="col-md-6"><select class="form-select" name="week" onchange="this.form.submit()"><?php foreach($weeks as $w):?><option value="<?=e($w['id'])?>" <?=$weekId===$w['id']?'selected':''?>><?=e(($w['week_label']?$w['week_label'].' · ':'').$w['title'])?></option><?php endforeach?></select></div><?php else:?><div class="col-md-4"><input class="form-control" type="month" name="month" value="<?=e($month)?>" onchange="this.form.submit()"></div><?php endif?></form></div><div class="row g-3"><div class="col-lg-7"><div class="card p-3 h-100"><h3 class="fw-bold">Xếp hạng lớp</h3><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Hạng</th><th>Lớp</th><th>Học sinh ghi điểm</th><th>Câu đúng</th><th>Điểm</th></tr></thead><tbody><?php foreach($classes as $i=>$r):?><tr><td><span class="rank <?=$i<3?'top':''?>"><?=$i+1?></span></td><td class="fw-bold"><?=e($r['class_name'])?></td><td><?=e($r['students'])?></td><td><?=e($r['correct'])?></td><td class="points"><?=e($r['points'])?></td></tr><?php endforeach;if(!$classes):?><tr><td colspan="5" class="text-center text-muted py-5">Chưa có điểm trong thời gian này.</td></tr><?php endif?></tbody></table></div></div></div><div class="col-lg-5"><div class="card p-3 h-100"><h3 class="fw-bold">Học sinh nổi bật</h3><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Học sinh</th><th>Lớp</th><th>Điểm</th></tr></thead><tbody><?php foreach($students as $r):?><tr><td><strong><?=e($r['student_name'])?></strong><div class="small text-muted"><?=e($r['correct'])?> câu đúng</div></td><td><?=e($r['class_name'])?></td><td class="points"><?=e($r['points'])?></td></tr><?php endforeach?></tbody></table></div></div></div></div></main></body></html>
